/**
 * Settings hub (/settings) — grouped rows into appearance / TTS / AI providers.
 * Mirrors desktop Settings panel sections (app/src/components/Settings), scoped
 * to what exists on mobile v1.
 */
import React, { type ReactNode } from "react";
import { Pressable, Text, View } from "react-native";
import { useRouter } from "expo-router";
import { SafeAreaView } from "react-native-safe-area-context";
import { Ionicons } from "@expo/vector-icons";
import { useT } from "@/hooks/useT";
import { usePalette } from "@/lib/theme";
import { Card, Divider, ListRow, tapHaptic } from "@/components/ui";

/** Small back-header for pushed settings screens (tabs hide the header). */
export function SettingsHeader({ title, right }: { title: string; right?: ReactNode }) {
  const p = usePalette();
  const router = useRouter();
  return (
    <View className="flex-row items-center justify-between px-2 pb-1 pt-2">
      <View className="flex-row items-center gap-1">
        <Pressable
          onPress={() => {
            tapHaptic();
            router.back();
          }}
          hitSlop={10}
          className="p-2"
        >
          <Ionicons name="chevron-back" size={24} color={p.foreground} />
        </Pressable>
        <Text className="text-[17px] font-semibold text-foreground">{title}</Text>
      </View>
      {right}
    </View>
  );
}

export default function SettingsScreen() {
  const t = useT();
  const p = usePalette();
  const router = useRouter();

  const rows: { key: string; icon: keyof typeof Ionicons.glyphMap; route: string }[] = [
    { key: "settings.appearance", icon: "color-palette-outline", route: "/settings/appearance" },
    { key: "settings.ttsSpeed", icon: "speedometer-outline", route: "/settings/tts" },
    { key: "settings.aiService", icon: "sparkles-outline", route: "/settings/ai" },
  ];

  return (
    <SafeAreaView className="flex-1 bg-background" edges={["top"]}>
      <SettingsHeader title={t("nav.settings")} />
      <View className="px-4 pt-2">
        <Card className="p-0">
          {rows.map((r, i) => (
            <View key={r.key}>
              {i > 0 ? <Divider className="mx-4" /> : null}
              <ListRow
                title={t(r.key)}
                left={
                  <View className="rounded-lg bg-muted p-1.5">
                    <Ionicons name={r.icon} size={18} color={p.foreground} />
                  </View>
                }
                onPress={() => router.push(r.route as never)}
              />
            </View>
          ))}
        </Card>
      </View>
    </SafeAreaView>
  );
}

/**
 * Appearance (/settings/appearance) — theme mode picker. Writes through
 * settingsStore.setSetting (persistence) + useSettingsStore.setState so the
 * root vars() theme switches instantly without a reload.
 */
import { View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { useT } from "@/hooks/useT";
import { SegmentedTabs } from "@/components/ui";
import { useSettingsStore, type ThemeMode } from "@/store/settingsStore";
import { SettingsHeader } from "./index";

export default function AppearanceScreen() {
  const t = useT();
  const themeMode = useSettingsStore((s) => s.themeMode);
  const setSetting = useSettingsStore((s) => s.setSetting);

  const onChange = async (v: ThemeMode) => {
    await setSetting("theme_mode", v).catch(() => {});
    useSettingsStore.setState({ themeMode: v });
  };

  return (
    <SafeAreaView className="flex-1 bg-background" edges={["top"]}>
      <SettingsHeader title={t("settings.appearance")} />
      <View className="px-4 pt-3">
        <SegmentedTabs<ThemeMode>
          options={[
            { key: "system", label: t("settings.theme.system") },
            { key: "light", label: t("settings.theme.light") },
            { key: "dark", label: t("settings.theme.dark") },
          ]}
          value={themeMode}
          onChange={(v) => void onChange(v)}
        />
      </View>
    </SafeAreaView>
  );
}

/**
 * TTS speed (/settings/tts) — picks expo-speech playback rate used by the
 * sentence/paragraph reading queue. Persisted to user_settings.tts_speed and
 * applied instantly via the settings store.
 */
import { View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { Ionicons } from "@expo/vector-icons";
import { useT } from "@/hooks/useT";
import { usePalette } from "@/lib/theme";
import { Card, Divider, ListRow, Text } from "./tts_parts";
import { useSettingsStore } from "@/store/settingsStore";
import { SettingsHeader } from "./index";

const SPEEDS = [0.75, 1, 1.25, 1.5];

export default function TtsScreen() {
  const t = useT();
  const p = usePalette();
  const ttsSpeed = useSettingsStore((s) => s.ttsSpeed);
  const setSetting = useSettingsStore((s) => s.setSetting);

  const onPick = async (v: number) => {
    await setSetting("tts_speed", String(v)).catch(() => {});
    useSettingsStore.setState({ ttsSpeed: v });
  };

  return (
    <SafeAreaView className="flex-1 bg-background" edges={["top"]}>
      <SettingsHeader title={t("settings.ttsSpeed")} />
      <View className="px-4 pt-3">
        <Card className="p-0">
          {SPEEDS.map((v, i) => (
            <View key={v}>
              {i > 0 ? <Divider className="mx-4" /> : null}
              <ListRow
                title={`${v}×`}
                right={
                  v === ttsSpeed ? (
                    <Ionicons name="checkmark" size={18} color={p.primary} />
                  ) : undefined
                }
                showChevron={false}
                onPress={() => void onPick(v)}
              />
            </View>
          ))}
        </Card>
      </View>
    </SafeAreaView>
  );
}

